package net.mcreator.minepiece.procedures;

import java.util.*;
import net.fabricmc.fabric.api.event.lifecycle.v1.*;
import net.fabricmc.fabric.api.networking.v1.ServerPlayConnectionEvents;
import net.mcreator.minepiece.entity.*;
import net.mcreator.minepiece.init.*;
import net.minecraft.server.level.*;
import net.minecraft.world.entity.*;
import net.minecraft.world.item.*;
import net.minecraft.world.phys.*;
import net.minecraft.world.level.ClipContext;
import net.minecraft.core.particles.ParticleTypes;

/** B07: source-shaped mythical/winged Zoans. Source audits and adaptations are kept with the batch. */
public final class MythicalZoanTechniques {
 public static final Item[] FRUITS={MinepieceModItems.ITEM_DEVIL_FRUIT_INU_INU_OKUCHI_NO_MAKAMI,MinepieceModItems.ITEM_DEVIL_FRUIT_HITO_HITO_DAIBUTSU,MinepieceModItems.ITEM_DEVIL_FRUIT_TORI_TORI_PHOENIX,MinepieceModItems.ITEM_DEVIL_FRUIT_UO_UO_SEIRYU,MinepieceModItems.ITEM_DEVIL_FRUIT_RYU_RYU_PTERANODON};
 public static final String[] NAMES={"makami","daibutsu","phoenix","seiryu","ptero"};
 public static final Item[] ANCIENT_FRUITS={MinepieceModItems.ITEM_DEVIL_FRUIT_RYU_RYU_BRACHIOSAURUS,MinepieceModItems.ITEM_DEVIL_FRUIT_RYU_RYU_PACHYCEPHALOSAURUS};
 public static final String[] ANCIENT_NAMES={"brachio","pachy"};
 public enum Kind { MISSILE,RED_LASER,BEAM,HEADLONG, OVERHEAD,SWEEP,THUNDER,RUSH,SLAM,ORB,ICE_BREATH,FIRE_BREATH,GUARD,BIRD,TORNADO,WAVE,SLASH,BEAK }
 private static final class Action {final ServerPlayer owner;final ServerLevel world;final Item fruit;final DevilFruitMove move;final Kind kind;final TechniqueTerrain.Budget terrain;final Set<UUID> hits=new HashSet<>();Vec3 look,start;int age;boolean stopped,landed;Action(ServerPlayer p,Item f,DevilFruitMove m){owner=p;world=(ServerLevel)p.level();fruit=f;move=m;kind=kind(f,m.id());terrain=TechniqueTerrain.begin(p,m);look=p.getLookAngle();start=p.position();}boolean valid(){return BatchRules.usable(owner,world,fruit);}}
 public static final class Shot {final Action action;final double radius;Shot(Action a,double r){action=a;radius=r;}public boolean valid(){return action.valid();}}
 private static final class Burn {final Action action;final LivingEntity target;int left=40;boolean ownsFire;Burn(Action a,LivingEntity t){action=a;target=t;ownsFire=t.getRemainingFireTicks()<=2;}}
 private static final Map<UUID,Action> ACTIVE=new HashMap<>();private static final Map<EntityGomuArmEntity,Action> VISUALS=new HashMap<>();private static final List<SkillProjectileEntity> SHOTS=new ArrayList<>();private static final Map<UUID,Burn> BURNS=new HashMap<>();
 private MythicalZoanTechniques(){}
 public static boolean handles(ItemStack fruit){return Arrays.asList(FRUITS).contains(fruit.getItem())||Arrays.asList(ANCIENT_FRUITS).contains(fruit.getItem());}
 public static String shortName(Item fruit){return Arrays.asList(ANCIENT_FRUITS).contains(fruit)?ANCIENT_NAMES[Arrays.asList(ANCIENT_FRUITS).indexOf(fruit)]:NAMES[Arrays.asList(FRUITS).indexOf(fruit)];}
 private static String batch(Item f){return Arrays.asList(ANCIENT_FRUITS).contains(f)?"b08_":"b07_";}
 public static String animationFor(ServerPlayer p,String id){var f=DevilFruitPowerLogic.getDevilFruit(p);return handles(f)?batch(f.getItem())+shortName(f.getItem())+"_"+id:"";}
 public static Kind kind(Item f,String id){return switch(id){case "brachiolauncher"->Kind.MISSILE;case "sparkingqueen"->Kind.RED_LASER;case "blackcofee"->Kind.BEAM;case "headbutt"->Kind.BEAK;case "ulzugan"->Kind.HEADLONG;case "brachiobober","attackjump","ulmeteor"->Kind.SLAM;case "attackoverhead","overheadsuper"->Kind.OVERHEAD;case "attacksweep","fujiazami"->Kind.SWEEP;case "raimeihakke"->Kind.THUNDER;case "attackspeed","brilliantpunk","ongle"->Kind.RUSH;case "himorogiri","kosanze","hooin"->Kind.SLAM;case "namujihyoga"->Kind.ICE_BREATH;case "borobreath"->Kind.FIRE_BREATH;case "hyogaheki"->Kind.GUARD;case "bluebird"->Kind.BIRD;case "marcotornado"->Kind.TORNADO;case "impactwave","ikoku"->Kind.WAVE;case "kaifu","barizodon"->Kind.SLASH;case "tankyudon"->Kind.BEAK;case "narikabura","impactball","kongokabura"->Kind.ORB;default->null;};}
 public static int windup(String id){return Set.of("brachiobober","attackjump","ulmeteor","ulzugan","blackcofee","borobreath","namujihyoga","impactwave","overheadsuper","himorogiri","kosanze","hyogaheki","ikoku").contains(id)?20:10;}
 public static int activeCount(){return ACTIVE.size();}public static int shotCount(){return (int)SHOTS.stream().filter(e->!e.isRemoved()).count();}
 public static boolean cast(ServerPlayer p,ItemStack fruit,DevilFruitMove m){if(!handles(fruit)||kind(fruit.getItem(),m.id())==null||ACTIVE.containsKey(p.getUUID())||!BatchRules.usable(p,(ServerLevel)p.level(),fruit.getItem()))return false;if(m.id().equals("hyogaheki")&&IceDefense.isActive(p))return false;var a=new Action(p,fruit.getItem(),m);ACTIVE.put(p.getUUID(),a);fx(a,batch(a.fruit)+shortName(a.fruit)+"_charge",p.getEyePosition().add(p.getLookAngle()),windup(m.id())+1,.2);return true;}
 public static void register(){ServerTickEvents.END_SERVER_TICK.register(s->tick());ServerPlayConnectionEvents.DISCONNECT.register((h,s)->cancel(h.player));ServerLifecycleEvents.SERVER_STOPPING.register(s->clear());}
 public static void cancel(ServerPlayer p){var a=ACTIVE.get(p.getUUID());if(a!=null&&a.owner==p)ACTIVE.remove(p.getUUID(),a);VISUALS.entrySet().removeIf(e->{if(e.getValue().owner!=p)return false;e.getKey().discard();return true;});for(var e:SHOTS)if(e.mythicalZoanShot.action.owner==p)e.discard();for(var b:new ArrayList<>(BURNS.values()))if(b.action.owner==p)endBurn(b);IceDefense.end(p,"retrait");FreezeService.clearFrom(p);}
 public static void clear(){var owners=new HashSet<ServerPlayer>();ACTIVE.values().forEach(a->owners.add(a.owner));VISUALS.values().forEach(a->owners.add(a.owner));SHOTS.forEach(e->owners.add(e.mythicalZoanShot.action.owner));BURNS.values().forEach(b->owners.add(b.action.owner));owners.forEach(MythicalZoanTechniques::cancel);SHOTS.clear();}
 public static void tick(){
  VISUALS.entrySet().removeIf(e->{if(!e.getValue().valid())e.getKey().discard();return e.getKey().isRemoved();});SHOTS.removeIf(e->{if(!e.mythicalZoanShot.valid())e.discard();return e.isRemoved();});
  for(var b:new ArrayList<>(BURNS.values())){var t=b.target;if(!b.action.valid()||!t.isAlive()||t.isRemoved()||t.level()!=b.action.world||t.isInWater()||t.fireImmune()||t.hasEffect(net.minecraft.world.effect.MobEffects.FIRE_RESISTANCE)||--b.left<0){endBurn(b);continue;}if(t.getRemainingFireTicks()>2)b.ownsFire=false;if(b.ownsFire)t.setRemainingFireTicks(2);if(b.left%20==0)CombatSkillLogic.hurtAndConfirm(t,b.action.world,CombatSkillLogic.elementalDamageSource(b.action.world,ElementType.FIRE,b.action.owner,null),1);if(b.left==0)endBurn(b);}
  for(var a:new ArrayList<>(ACTIVE.values())){if(!a.valid()){cancel(a.owner);continue;}int t=++a.age-windup(a.move.id());if(t<0)continue;if(t==0){a.look=a.owner.getLookAngle();a.start=a.owner.position();TechniqueAnimations.playNamed(a.owner,animationFor(a.owner,a.move.id())+"_release");release(a);}
   if((a.kind==Kind.RUSH||a.kind==Kind.THUNDER||a.kind==Kind.BEAK||a.kind==Kind.HEADLONG)&&t<(a.kind==Kind.HEADLONG?14:12)&&!a.stopped){double moved=move(a,a.owner.position().add(flat(a.look).scale(a.kind==Kind.HEADLONG?.9:.55)));hit(a,a.owner.getEyePosition().add(a.look.scale(1.2)),2.2,true,a.move.damage());if(t%2==0)fx(a,profile(a),a.owner.getEyePosition().add(a.look),10,1.1);if(moved<(a.kind==Kind.HEADLONG?.8:.45)||t==(a.kind==Kind.HEADLONG?13:11)){a.stopped=true;var ray=ray(a,a.owner.getEyePosition(),a.look,2);a.terrain.impact(ray.getLocation());}}
   if(a.kind==Kind.SLAM&&t<28&&!a.landed){var next=a.start.add(flat(a.look).scale((t+1)*(a.move.id().equals("ulmeteor")?12.0/28:.25))).add(0,Math.sin((t+1)*Math.PI/28)*4,0);var delta=next.subtract(a.owner.position());double moved=move(a,next);if(t==27||(moved+.05<delta.length()&&t>=14)){a.landed=true;hit(a,a.owner.position(),4.5,false,a.move.damage());a.terrain.impact(a.owner.position().add(0,-.1,0));fx(a,profile(a),a.owner.position(),24,4);}}
   if((a.kind==Kind.ICE_BREATH||a.kind==Kind.FIRE_BREATH)&&t<20)breath(a,t);
   if(a.kind==Kind.WAVE&&t<20&&!a.stopped){Vec3 from=a.start.add(0,1.2,0),to=from.add(a.look.scale((t+1)*(a.move.id().equals("ikoku")?1:.6)));var collision=a.world.clip(new ClipContext(from,to,ClipContext.Block.COLLIDER,ClipContext.Fluid.NONE,a.owner));if(collision.getType()==HitResult.Type.BLOCK){a.stopped=true;a.terrain.impact(collision.getLocation());}else{hit(a,to,2.2,false,a.move.damage());a.terrain.impact(to);if(t%2==0)fx(a,profile(a),to,12,2);}}
   if(a.kind==Kind.TORNADO&&t<24){Vec3 from=a.start.add(0,1,0),at=from.add(flat(a.look).scale(t*.3));var collision=ray(a,from,flat(a.look),t*.3);if(collision.getType()==HitResult.Type.BLOCK){a.stopped=true;a.terrain.impact(collision.getLocation());}if(!a.stopped){hit(a,at,3,false,a.move.damage());a.terrain.impact(at);if(t%3==0)fx(a,profile(a),at,14,3);}}
   if(t>=75)ACTIVE.remove(a.owner.getUUID(),a);
  }
 }
 private static String profile(Action a){return batch(a.fruit)+shortName(a.fruit)+"_"+a.move.id();}
 /** Include the exact endpoint: a fractional movement is not a collision or a landing. */
 private static double move(Action a,Vec3 destination){Vec3 start=a.owner.position(),delta=destination.subtract(start),last=start;double distance=delta.length();if(distance<.00001)return 0;int steps=(int)Math.ceil(Math.min(48,distance)/.2);for(int i=1;i<=steps;i++){Vec3 next=start.add(delta.scale((double)i/steps));if(!SafeDestination.isSafe(a.world,a.owner,next))break;last=next;}a.owner.teleportTo(last.x,last.y,last.z);a.owner.setDeltaMovement(Vec3.ZERO);a.owner.syncVelocity=true;return last.distanceTo(start);}
 private static Vec3 flat(Vec3 v){var f=new Vec3(v.x,0,v.z);return f.lengthSqr()<.0001?new Vec3(0,0,1):f.normalize();}
 private static BlockHitResult ray(Action a,Vec3 from,Vec3 direction,double range){return a.world.clip(new ClipContext(from,from.add(direction.scale(range)),ClipContext.Block.COLLIDER,ClipContext.Fluid.NONE,a.owner));}
 private static EntityGomuArmEntity fx(Action a,String id,Vec3 at,int ttl,double size){var e=GoroTechniques.visual(a.owner,id,at,ttl);e.setStretch((float)size);VISUALS.put(e,a);return e;}
 private static void release(Action a){switch(a.kind){
  case OVERHEAD,SWEEP->{Vec3 at=a.owner.position().add(flat(a.look).scale(2));double r=a.kind==Kind.SWEEP?3:3.5;hit(a,at,r,a.kind==Kind.OVERHEAD,a.move.damage());var impact=ray(a,a.owner.getEyePosition(),a.look,3);a.terrain.impact(impact.getLocation());fx(a,profile(a),at,24,r);}
  case GUARD->{IceDefense.begin(a.owner);fx(a,profile(a),a.owner.position(),Math.min(200,br.com.oneminepiece.opworldlike.inu.DevilFruitOkuchiConfig.defenseDurationTicks()),1.5);}
  case BEAM->beam(a);
  case MISSILE->shoot(a,profile(a),2.5,1.05,0);
  case RED_LASER->shoot(a,profile(a),.55,2,0);
  case ORB->shoot(a,profile(a),.8,1.1,0);
  case BIRD->shoot(a,profile(a),1.1,1.1,0);
  case SLASH->{if(a.move.id().equals("kaifu"))for(int i=-1;i<=1;i++)shoot(a,profile(a),.7,1.3,i*.17);else shoot(a,profile(a),.7,1.6,0);}
  default->{}
 }}
 private static ElementType element(Action a){if(a.kind==Kind.BEAM||a.kind==Kind.RED_LASER)return ElementType.LIGHT;return a.kind==Kind.ICE_BREATH||a.fruit==FRUITS[0]&&Set.of("narikabura","himorogiri").contains(a.move.id())?ElementType.ICE:a.kind==Kind.FIRE_BREATH?ElementType.FIRE:ElementType.PHYSICAL;}
 private static void confirmed(Action a,LivingEntity target){if(a.fruit==FRUITS[0]&&!Set.of("attackoverhead","raimeihakke").contains(a.move.id()))FreezeService.apply(target,60,a.owner);if(a.kind==Kind.FIRE_BREATH&&!target.fireImmune()&&!target.hasEffect(net.minecraft.world.effect.MobEffects.FIRE_RESISTANCE)&&!BURNS.containsKey(target.getUUID()))BURNS.put(target.getUUID(),new Burn(a,target));}
 private static void hit(Action a,Vec3 at,double radius,boolean cone,double damage){var source=CombatSkillLogic.elementalDamageSource(a.world,element(a),a.owner,null);for(var t:a.world.getEntitiesOfClass(LivingEntity.class,new AABB(at,at).inflate(radius))){if(a.hits.contains(t.getUUID())||t.getBoundingBox().distanceToSqr(at)>radius*radius||!BatchRules.target(a.owner,t))continue;if(cone&&t.getBoundingBox().getCenter().subtract(a.owner.getEyePosition()).normalize().dot(a.look)<.35)continue;if(CombatSkillLogic.hurtAndConfirm(t,a.world,source,(float)damage)){a.hits.add(t.getUUID());confirmed(a,t);CombatSkillLogic.applySkillKnockback(t,a.look,source,a.move.knockback());}}}
 private static void breath(Action a,int tick){Vec3 from=a.owner.getEyePosition();var block=ray(a,from,a.look,18);double length=block.getLocation().distanceTo(from);for(var t:a.world.getEntitiesOfClass(LivingEntity.class,new AABB(from,block.getLocation()).inflate(2.5))){Vec3 center=t.getBoundingBox().getCenter(),relative=center.subtract(from);double along=relative.dot(a.look);if(along<0||along>length||relative.subtract(a.look.scale(along)).length()>1+along*.06||!BatchRules.target(a.owner,t))continue;if(!a.hits.contains(t.getUUID()))hit(a,center,.1,false,a.move.damage());else if(a.kind==Kind.ICE_BREATH&&(tick==6||tick==12))FreezeService.apply(t,60,a.owner);}
  if(a.kind==Kind.ICE_BREATH)a.terrain.freezePath(a.owner.position(),a.look,Math.min(length,12));else if(block.getType()==HitResult.Type.BLOCK)a.terrain.impact(block.getLocation());
  if(tick%2==0){for(double d=1;d<=length;d+=2)fx(a,profile(a),from.add(a.look.scale(d)),8,.4+d*.035);}
 }
 private static void beam(Action a){Vec3 from=a.owner.getEyePosition();var block=ray(a,from,a.look,24);double length=from.distanceTo(block.getLocation());for(var target:a.world.getEntitiesOfClass(LivingEntity.class,new AABB(from,block.getLocation()).inflate(1))){Vec3 relative=target.getBoundingBox().getCenter().subtract(from);double along=relative.dot(a.look);if(along>=0&&along<=length&&relative.subtract(a.look.scale(along)).length()<=1&&BatchRules.target(a.owner,target))hit(a,target.getBoundingBox().getCenter(),.1,false,a.move.damage());}for(double d=.5;d<=length;d+=1.25)fx(a,profile(a),from.add(a.look.scale(d)),12,.09);if(block.getType()==HitResult.Type.BLOCK)a.terrain.impact(block.getLocation());}
 private static void shoot(Action a,String profile,double radius,double speed,double angle){Vec3 dir=a.look.yRot((float)angle),at=a.owner.getEyePosition().add(dir.scale(.4));var e=new SkillProjectileEntity(MinepieceModEntities.SKILL_PROJECTILE,at.x,at.y,at.z,dir,a.world);e.setOwner(a.owner);e.model("note_3d").texture("clear").visualProfile(profile).damage(a.move.damage()).element(element(a)).lifetime(50).range(32).scale(.4F).trail(a.kind==Kind.MISSILE?ParticleTypes.SMOKE:a.fruit==FRUITS[2]?MinepieceModParticles.FLAME_BLUE:ParticleTypes.END_ROD);e.mythicalZoanShot=new Shot(a,radius);e.accelerationPower=0;e.shoot(dir.x,dir.y,dir.z,(float)speed,0);a.world.addFreshEntity(e);SHOTS.add(e);}
 public static void impact(SkillProjectileEntity e,Vec3 at,LivingEntity direct){var s=e.mythicalZoanShot;if(s==null||!s.valid())return;var a=s.action;var source=CombatSkillLogic.elementalDamageSource(a.world,element(a),a.owner,e);for(var t:a.world.getEntitiesOfClass(LivingEntity.class,new AABB(at,at).inflate(s.radius))){if(a.hits.contains(t.getUUID())||!BatchRules.offensiveTarget(a.owner,t)||t.getBoundingBox().distanceToSqr(at)>s.radius*s.radius)continue;if(ray(a,at,t.getBoundingBox().getCenter().subtract(at).normalize(),at.distanceTo(t.getBoundingBox().getCenter())).getType()!=HitResult.Type.MISS)continue;if(CombatSkillLogic.hurtAndConfirm(t,a.world,source,(float)(a.kind==Kind.MISSILE?13.5+(t==direct?a.move.damage():0):a.move.damage()))){a.hits.add(t.getUUID());confirmed(a,t);CombatSkillLogic.applySkillKnockback(t,e.getDeltaMovement(),source,a.move.knockback());}}a.terrain.impact(at);fx(a,batch(a.fruit)+shortName(a.fruit)+"_impact",at,16,.8);}
 private static void endBurn(Burn b){BURNS.remove(b.target.getUUID(),b);if(b.ownsFire&&b.target.getRemainingFireTicks()<=2)b.target.setRemainingFireTicks(0);}
}
